/* VietFarmy Gallery - Lightbox */
/* Based on Simple Lightbox - https://github.com/simplelightbox/Simple-Lightbox */
(function($) {
    'use strict';

    $.fn.vnfLightbox = function(options) {
        var settings = $.extend({
            selector: '.vnf-gl-lightbox',
            parent: 'body',
            animate: true,
            animationSpeed: 250,
            imageErrorText: 'Hình ảnh không thể tải',
            nextText: 'Tiếp',
            prevText: 'Trước',
            closeText: 'Đóng',
            loadingText: 'Đang tải...',
            closeOnClick: true,
            closeOnSwipe: true,
            history: true
        }, options);

        var currentIndex = 0;
        var $items = $(this);
        var $overlay = null;
        var $container = null;
        var $image = null;
        var $title = null;
        var $loading = null;

        function createUI() {
            $overlay = $('<div class="vnf-gl-lb-overlay"></div>').hide().appendTo(settings.parent);
            $container = $('<div class="vnf-gl-lb-container"></div>').hide().appendTo(settings.parent);

            $loading = $('<div class="vnf-gl-lb-loading">' + settings.loadingText + '</div>');
            $image = $('<img class="vnf-gl-lb-image" alt="">');
            $title = $('<div class="vnf-gl-lb-title"></div>');

            var $nav = $('<div class="vnf-gl-lb-nav"></div>');
            var $prev = $('<button class="vnf-gl-lb-prev" title="' + settings.prevText + '">&#10094;</button>');
            var $next = $('<button class="vnf-gl-lb-next" title="' + settings.nextText + '">&#10095;</button>');
            var $close = $('<button class="vnf-gl-lb-close" title="' + settings.closeText + '">&#10005;</button>');

            $container.append($loading, $image, $title, $nav.append($prev, $next, $close));

            // Events
            $overlay.on('click', function() { if (settings.closeOnClick) close(); });
            $close.on('click', close);
            $prev.on('click', prev);
            $next.on('click', next);

            // Keyboard
            $(document).on('keydown.vnflb', function(e) {
                if ($overlay.is(':visible')) {
                    if (e.key === 'Escape') close();
                    if (e.key === 'ArrowLeft') prev();
                    if (e.key === 'ArrowRight') next();
                }
            });

            // Touch swipe
            var touchStartX = 0;
            $container.on('touchstart', function(e) {
                touchStartX = e.originalEvent.touches[0].clientX;
            });
            $container.on('touchend', function(e) {
                if (!settings.closeOnSwipe) return;
                var dx = e.originalEvent.changedTouches[0].clientX - touchStartX;
                if (Math.abs(dx) > 50) {
                    dx < 0 ? next() : prev();
                }
            });
        }

        function open(index) {
            currentIndex = index;
            $overlay.fadeIn(settings.animationSpeed);
            $container.show();
            if (settings.animate) $container.css({ opacity: 0 });
            showImage();
            if (settings.animate) $container.animate({ opacity: 1 }, settings.animationSpeed);
            $('body').css('overflow', 'hidden');
        }

        function close() {
            $container.animate({ opacity: 0 }, settings.animationSpeed, function() {
                $container.hide();
                $overlay.fadeOut(settings.animationSpeed);
                $('body').css('overflow', '');
            });
        }

        function showImage() {
            var $item = $items.eq(currentIndex);
            var src = $item.attr('href');
            var title = $item.data('title') || '';

            $loading.show();
            $image.hide();
            $title.text(title).hide();

            $image.off('load error').on('load', function() {
                $loading.hide();
                $image.show();
                if (title) $title.show();
                preloadAdjacent();
            }).on('error', function() {
                $loading.text(settings.imageErrorText);
            }).attr('src', src);
        }

        function prev() {
            currentIndex = (currentIndex - 1 + $items.length) % $items.length;
            showImage();
        }

        function next() {
            currentIndex = (currentIndex + 1) % $items.length;
            showImage();
        }

        function preloadAdjacent() {
            var nextImg = new Image();
            nextImg.src = $items.eq((currentIndex + 1) % $items.length).attr('href');
        }

        // Initialize
        createUI();

        return this.on('click.vnflb', function(e) {
            e.preventDefault();
            open($items.index(this));
        });
    };

    // Auto-init on data-lightbox
    $(document).ready(function() {
        $('[data-lightbox]').each(function() {
            $(this).vnfLightbox();
        });
    });

}(jQuery));